// Ability score summary per class (for the hex display in SkillCard art window)
// Derived conceptually, not mathematically, from the skill table above
const CLASS_ABILITY_SCORES={
  Fighter:   {STR:+2,DEX: 0,CON:+1,INT: 0,WIS:-1,CHA:-1},
  Monk:      {STR:+2,DEX:+1,CON:+1,INT: 0,WIS:+1,CHA:-1},
  Barbarian: {STR:+3,DEX: 0,CON:+2,INT:-1,WIS:-1,CHA: 0},
  Wizard:    {STR:-1,DEX:-1,CON: 0,INT:+2,WIS:+1,CHA:-1},
  Artificer: {STR:-1,DEX:+1,CON: 0,INT:+2,WIS: 0,CHA:-1},
  Rogue:     {STR:-1,DEX:+2,CON: 0,INT:+1,WIS:+1,CHA: 0},
  Healer:    {STR:-1,DEX:-1,CON: 0,INT:-1,WIS:+2,CHA:+1},
  Bard:      {STR:-1,DEX: 0,CON: 0,INT:-1,WIS:+1,CHA:+2},
  Champion:  {STR: 0,DEX:-1,CON:+1,INT: 0,WIS:+1,CHA:+2},
  Ranger:    {STR: 0,DEX:+2,CON: 0,INT:-1,WIS:+1,CHA: 0},
  Sorcerer:  {STR:-1,DEX:+1,CON:-1,INT:+1,WIS: 0,CHA:+2},
  Druid:     {STR:-1,DEX: 0,CON:+1,INT:+1,WIS:+2,CHA: 0},
};
function deriveAbilityScores(sb,colorKey,scores,className){
  // Use class-specific table if className provided, fall back to save-based derivation
  if(className&&CLASS_ABILITY_SCORES[className]) return CLASS_ABILITY_SCORES[className];
  // Fallback for dual classes
  const fort=pipMod(sb.fort),ref=pipMod(sb.ref),will=pipMod(sb.will);
  const ps=scores?.PURPLE||0;
  const bg=Math.max(scores?.BLUE||0,scores?.GREEN||0);
  return{
    STR:fort, DEX:ref, CON:Math.max(-1,fort-1),
    INT:ps>=8?2:ps>=5?1:ps>=3?0:-1,
    WIS:will, CHA:bg>=8?2:bg>=5?1:bg>=3?0:-1,
  };
}

// Proficiency bonus by class tier
function profBonus(cn){
  return["Barbarian","Rogue","Champion","Druid"].includes(cn)?4:
         ["Monk","Artificer","Bard","Sorcerer"].includes(cn)?3:2;
}

// Build the full computed skill list for a character
// NOTE: Beginner tier (pre-workshop) — no proficiency bonus applied.
// Proficiency unlocks through the Hero's Journey Workshop campaign.
function buildSkillList(className,sb,colorKey,scores,rawAnswers){
  const base=CLASS_SKILL_MODS[className]||{};
  const profs=new Set(CLASS_PROFICIENCIES[className]||[]);
  // Each answer contributes 1/20 of a +1 to relevant skills.
  // 20 answers all pointing at the same skill = +1.0 max quiz contribution.
  // In practice 4-6 answers = +0.2 to +0.3 — a gentle nudge, never dominates.
  const ANSWER_WEIGHT=1/20;
  const quizRaw={};
  if(rawAnswers){
    Object.entries(rawAnswers).forEach(([qIdx,color])=>{
      const skills=Q_SKILL_MAP[parseInt(qIdx)]?.[color]||[];
      skills.forEach(sk=>{ quizRaw[sk]=(quizRaw[sk]||0)+ANSWER_WEIGHT; });
    });
  }
  return SKILLS.map(sk=>{
    const b=base[sk.name]??0;
    const qRaw=quizRaw[sk.name]||0;
    const combined=b+qRaw;
    const total=Math.max(-2,Math.min(3,Math.round(combined))); // whole integers only
    const quizBonusInt=Math.round(qRaw); // 1 when answers push modifier up by a full point
    return{...sk,abMod:b,quizBonus:quizBonusInt,isProficient:profs.has(sk.name),total};
  }).sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name));
}

// ── Skill Card ─────────────────────────────────────────────────────────────────
function SkillCard({className,sb,colorKey,scores,rawAnswers,accent,accent2}){
  const skillList=buildSkillList(className,sb,colorKey,scores,rawAnswers);
  const abs=deriveAbilityScores(sb,colorKey,scores,className);
  const _prof=profBonus(className); // eslint-disable-line no-unused-vars

  // eslint-disable-next-line no-unused-vars
  const AB_LABEL={STR:"STR",DEX:"DEX",CON:"CON",INT:"INT",WIS:"WIS",CHA:"CHA"};
  const AB_COLOR={
    STR:"#C0392B",DEX:"#1E8449",CON:"#935116",
    INT:"#6C3483",WIS:"#1A5276",CHA:"#2E86C1",
  };

  // Grouped by ability score for the header row
  const AB_ORDER=["STR","DEX","CON","INT","WIS","CHA"];
  const fmtMod=n=>n>=0?`+${n}`:String(n);

  return(
    <CardShell accent={accent} accent2={accent2||accent}>
      {/* Art window — ability score hexes */}
      <div style={{width:"100%",height:180,background:`linear-gradient(160deg,${accent}12,#0D0D12 80%)`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,position:"relative",overflow:"hidden"}}>
        {/* Ability score hex grid */}
        <div style={{display:"flex",gap:6,flexWrap:"wrap",justifyContent:"center",padding:"16px 20px"}}>
          {AB_ORDER.map(ab=>(
            <div key={ab} style={{
              width:56,height:56,borderRadius:10,
              background:AB_COLOR[ab]+"22",
              border:`1px solid ${AB_COLOR[ab]}55`,
              display:"flex",flexDirection:"column",
              alignItems:"center",justifyContent:"center",
              gap:1,
            }}>
              <div style={{fontSize:16,fontWeight:700,color:"#F0EDE6",lineHeight:1}}>{fmtMod(abs[ab])}</div>
              <div style={{fontSize:8,letterSpacing:"0.12em",color:AB_COLOR[ab],textTransform:"uppercase",opacity:0.85}}>{ab}</div>
            </div>
          ))}
        </div>
        <div style={{position:"absolute",bottom:0,left:0,right:0,height:40,background:"linear-gradient(transparent,#0D0D12)"}}/>
        <div style={{position:"absolute",top:12,right:14,fontSize:9,color:accent,opacity:0.45,letterSpacing:"0.2em",textTransform:"uppercase"}}>Skills</div>
        {/* Beginner tier badge */}
        <div style={{position:"absolute",top:12,left:14,background:"rgba(255,255,255,0.06)",borderRadius:20,padding:"3px 8px",border:"1px solid rgba(255,255,255,0.12)"}}>
          <span style={{fontSize:9,color:"#8a7f6e",letterSpacing:"0.08em"}}>Beginner · No proficiency yet</span>
        </div>
      </div>

      {/* Skill list */}
      <div style={{padding:"10px 16px 14px",flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
        <div style={{fontSize:9,letterSpacing:"0.2em",color:accent,textTransform:"uppercase",marginBottom:10,opacity:0.8}}>Skill Modifiers</div>

        <div style={{flex:1,display:"flex",flexDirection:"column",gap:3,overflowY:"auto"}}>
          {skillList.map(sk=>(
            <div key={sk.name} style={{
              display:"flex",alignItems:"center",gap:8,
              padding:"4px 8px",borderRadius:6,
              background:sk.isProficient?`${accent}12`:"transparent",
              border:sk.isProficient?`1px solid ${accent}28`:"1px solid transparent",
            }}>
              {/* Proficiency dot — filled = will unlock at workshop; empty = untrained */}
              <div style={{
                width:6,height:6,borderRadius:"50%",flexShrink:0,
                background:"transparent",
                border:sk.isProficient?`1.5px solid ${accent}`:"1.5px solid rgba(255,255,255,0.15)",
                boxShadow:sk.isProficient?`0 0 4px ${accent}55`:"none",
              }}/>

              {/* Modifier + quiz bonus indicator */}
              <div style={{display:"flex",alignItems:"baseline",gap:3,minWidth:44,justifyContent:"flex-end"}}>
                <div style={{
                  fontSize:13,fontWeight:700,
                  color:sk.total>0?accent:sk.total<0?"#c08080":"#8a7f6e",
                  fontFamily:"Georgia,serif",
                }}>
                  {fmtMod(sk.total)}
                </div>
                {sk.quizBonus>=1&&(
                  <div style={{fontSize:8,color:accent,opacity:0.55,fontFamily:"sans-serif"}}>
                    ✦
                  </div>
                )}
              </div>

              {/* Skill name */}
              <div style={{flex:1,fontSize:11,color:sk.isProficient?"#F0EDE6":"#c9c1b0",fontWeight:sk.isProficient?600:400}}>
                {sk.name}
              </div>

              {/* Ability tag */}
              <div style={{
                fontSize:8,color:AB_COLOR[sk.ab],letterSpacing:"0.1em",
                background:AB_COLOR[sk.ab]+"18",borderRadius:4,padding:"1px 5px",
                flexShrink:0,
              }}>
                {sk.ab}
              </div>
            </div>
          ))}
        </div>

        {/* EQ label row — show top 3 proficient skills' EQ tags */}
        <div style={{marginTop:8,paddingTop:8,borderTop:`1px solid ${accent}18`}}>
          <div style={{fontSize:8,letterSpacing:"0.15em",color:"#8a7f6e",textTransform:"uppercase",marginBottom:5}}>⬡ Workshop Unlocks (dotted = future proficiency)</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:4}}>
            {skillList.filter(sk=>sk.isProficient).map(sk=>(
              <div key={sk.name} style={{fontSize:8,color:accent,opacity:0.7,background:`${accent}12`,borderRadius:4,padding:"2px 6px",fontStyle:"italic"}}>
                {sk.eq}
              </div>
            ))}
          </div>
        </div>

        <div style={{marginTop:8,display:"flex",justifyContent:"space-between"}}>
          <span style={{fontSize:8,color:"#F0EDE6",opacity:0.18,letterSpacing:"0.15em",textTransform:"uppercase"}}>Skill Card</span>
          <span style={{fontSize:8,color:"#F0EDE6",opacity:0.12,fontFamily:"serif"}}>Elarion</span>
        </div>
      </div>
    </CardShell>
  );
}

// ── Full Card Reveal Screen ────────────────────────────────────────────────────
function CardRevealScreen({result,playerName,onClose,reset,onDownloadPDF,generating,pdfError}){
  const [panelIdx,setPanelIdx]=useState(0);
  useEffect(()=>{ window.scrollTo({top:0,behavior:"instant"}); },[]);
  const resolved=result.resolved||{type:"single",colors:[result.topColor],influence:[]};
  const isTie=resolved.type==="dual"||resolved.type==="shapeshifter";
  const data=CLASSES[result.topColor];
  const myScore=result.scores[result.topColor];
  const myClass=getClass(data,myScore);
  const cd=data.classData?data.classData[myClass]:null;
  const dualProfile=isTie?getDualProfile(resolved):null;
  const insight=buildInsight(result.rawAnswers||{},result.scores,result.topColor,isTie?[]:resolved.influence||[],null);
  const accent = isTie&&dualProfile?dualProfile.color1:data.color;

  const getDualSBKey=(dp)=>{
    if(!dp)return"ALL";
    const order=["BLUE","GREEN","PURPLE","RED"];
    const c1=resolved.colors[0]||"RED",c2=resolved.colors[1]||"PURPLE";
    return[c1,c2].sort((a,b)=>order.indexOf(a)-order.indexOf(b)).join("_");
  };
  const sb = isTie ? (DUAL_STAT_BLOCKS[getDualSBKey(dualProfile)]||DUAL_STAT_BLOCKS["ALL"]) : (STAT_BLOCKS[myClass]||{});

  const rawAns=result.rawAnswers||{};
  const primaryColorAnswers=new Set(Object.entries(rawAns).filter(([,c])=>c===result.topColor).map(([i])=>parseInt(i)));
  const scoreAbility=(ab)=>{const qs=ABILITY_Q_MAP[ab.name]||[];return qs.filter(q=>primaryColorAnswers.has(q)).length;};
  const baseAbilities=isTie&&dualProfile?dualProfile.abilities:(cd?cd.abilities:[]);
  const singleLockedName=cd?cd.locked:null;
  const isAbilityLocked=(ab)=>isTie&&dualProfile?ab.locked:(ab.name===singleLockedName||ab.desc?.startsWith("LOCKED."));
  const displayAbilities=[
    ...baseAbilities.filter(ab=>!isAbilityLocked(ab)).sort((a,b)=>scoreAbility(b)-scoreAbility(a)),
    ...baseAbilities.filter(ab=>isAbilityLocked(ab)),
  ];
  const displayQuest=isTie&&dualProfile?dualProfile.quest:(cd?cd.quest:"");

  const panels=[
    {
      label:"Hero Card",
      content:(
        <HeroCard
          colorKey={result.topColor}
          className={myClass}
          dualProfile={dualProfile}
          resolvedColors={resolved.colors||[]}
          isTie={isTie}
          scores={result.scores}
          data={data}
          rawAnswers={result.rawAnswers||{}}
        />
      )
    },
    {
      label:"Ability Cards",
      content:(
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {sb.passive&&(
            <AbilityCardFull ability={sb.passive} accent={accent} index={0} isLocked={false} isSig={false} isPassive={true}/>
          )}
          {displayAbilities.map((ab,i)=>{
            const isSig=sb.sigAbility&&ab.name===sb.sigAbility.name;
            const displayAb=isSig&&sb.sigAbility?{...ab,desc:sb.sigAbility.desc,actions:sb.sigAbility.actions}:ab;
            return(
              <AbilityCardFull
                key={i}
                ability={displayAb}
                accent={isTie&&dualProfile&&ab.lean1?({RED:"#C0392B",PURPLE:"#6C3483",BLUE:"#1A5276",GREEN:"#1E8449"}[ab.lean1]||accent):accent}
                index={i+(sb.passive?1:0)}
                isLocked={isAbilityLocked(ab)}
                isSig={!!isSig}
                isPassive={false}
              />
            );
          })}
        </div>
      )
    },
    {
      label:"Quest Card",
      content:<QuestCard quest={displayQuest} personalisedQuest={insight?.personalisedQuest} accent={accent}/>
    },
    {
      label:"Skill Card",
      content:(
        <SkillCard
          className={myClass}
          sb={sb}
          colorKey={result.topColor}
          scores={result.scores}
          rawAnswers={result.rawAnswers||{}}
          accent={accent}
          accent2={isTie&&dualProfile?dualProfile.color2:data.color}
        />
      )
    },
    {
      label:"Trigger Card",
      content:<TriggerCard sb={sb} accent={accent} className={myClass} dualProfile={dualProfile} isTie={isTie} resolved={resolved}/>
    },
    ...(sb.dynamics?[{
      label:"Dynamics Card",
      content:<DynamicsCard sb={sb} accent={accent}/>
    }]:[]),
    {
      label:"Download",
      content:(
        <div style={{textAlign:"center",padding:"28px 22px",background:"rgba(255,255,255,0.02)",borderRadius:14,border:"1px solid rgba(255,255,255,0.08)"}}>
          <p style={{fontSize:13,color:"#8a7f6e",margin:"0 0 8px",lineHeight:1.75}}>Your locked abilities are revealed in the Hero's Journey Workshop.</p>
          <p style={{fontSize:11,color:"#6a6050",margin:"0 0 24px",fontStyle:"italic"}}>Print these cards → cut them out → bring them to Day 1.</p>
          <div style={{display:"flex",flexDirection:"column",gap:12,alignItems:"center"}}>
            <button
              onClick={onDownloadPDF}
              disabled={generating}
              style={{background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"13px 28px",color:generating?"#6a5e3a":"#c8b97e",cursor:generating?"not-allowed":"pointer",fontFamily:"Georgia",fontSize:13,display:"flex",alignItems:"center",gap:8,opacity:generating?0.6:1,width:"100%",maxWidth:280,justifyContent:"center"}}
            >
              {generating ? "⏳ Generating PDF…" : "⬇ Download PDF"}
            </button>
            {pdfError&&<p style={{margin:"4px 0 0",fontSize:11,color:"#c0392b",textAlign:"center"}}>{pdfError}</p>}
            <button
              onClick={()=>{
                const style=document.createElement("style");
                style.id="print-card-styles";
                style.textContent=`@media print{body>*:not(#card-print-root){display:none!important;}#card-print-root{display:block!important;}@page{size:A4 portrait;margin:12mm;}.print-card-grid{display:grid!important;grid-template-columns:repeat(2,1fr);gap:8mm;page-break-inside:avoid;}.print-card{break-inside:avoid;page-break-inside:avoid;}body{background:#fff!important;}}`;
                document.head.appendChild(style);
                const root=document.createElement("div");
                root.id="card-print-root";
                root.style.display="none";
                root.style.position="fixed";
                root.style.inset="0";
                root.style.background="#fff";
                root.style.zIndex="99999";
                document.body.appendChild(root);
                window.print();
                setTimeout(()=>{document.head.removeChild(style);document.body.removeChild(root);},1000);
              }}
              style={{background:`linear-gradient(135deg,${accent},${accent}cc)`,border:"none",borderRadius:8,padding:"13px 28px",color:"#fff",fontWeight:700,fontFamily:"Georgia",fontSize:14,cursor:"pointer",letterSpacing:"0.05em",display:"flex",alignItems:"center",gap:8,width:"100%",maxWidth:280,justifyContent:"center"}}
            >
              🖨 Print Character Cards
            </button>
            <button onClick={reset} style={{background:"none",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"13px 28px",color:"#8a7f6e",cursor:"pointer",fontFamily:"Georgia",fontSize:13,width:"100%",maxWidth:280}}>
              Retake Test
            </button>
          </div>
        </div>
      )
    },
  ];

  const total=panels.length;
  const prev=()=>setPanelIdx(i=>Math.max(0,i-1));
  const next=()=>setPanelIdx(i=>Math.min(total-1,i+1));

  // Touch/swipe support
  const touchStartX=React.useRef(null);
  const onTouchStart=(e)=>{ touchStartX.current=e.touches[0].clientX; };
  const onTouchEnd=(e)=>{
    if(touchStartX.current===null)return;
    const dx=touchStartX.current-e.changedTouches[0].clientX;
    if(Math.abs(dx)>40){ dx>0?next():prev(); }
    touchStartX.current=null;
  };

  return(
    <div style={{minHeight:"100vh",background:"#080810",fontFamily:"'Georgia',serif",color:"#e8e4d9",overflow:"hidden",display:"flex",flexDirection:"column"}}>
      <style>{`
        @keyframes revealIn{from{opacity:0;transform:translateY(20px) scale(0.97)}to{opacity:1;transform:none}}
        @keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
        @keyframes fadeIn{from{opacity:0}to{opacity:1}}
        ::-webkit-scrollbar{display:none}
      `}</style>

      {/* Top bar */}
      <div style={{padding:"16px 20px",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:"1px solid rgba(255,255,255,0.06)",flexShrink:0}}>
        <button onClick={onClose} style={{background:"none",border:"none",color:"#8a7f6e",cursor:"pointer",fontSize:13,fontFamily:"Georgia",display:"flex",alignItems:"center",gap:6}}>
          ← Back
        </button>
        <div style={{fontSize:10,letterSpacing:"0.25em",color:"#b7950b",textTransform:"uppercase"}}>{panels[panelIdx].label}</div>
        <div style={{fontSize:11,color:"#4a4438",fontFamily:"Georgia"}}>{panelIdx+1} / {total}</div>
      </div>

      {/* Carousel viewport */}
      <div
        style={{flex:1,overflow:"hidden",position:"relative"}}
        onTouchStart={onTouchStart}
        onTouchEnd={onTouchEnd}
      >
        <div style={{
          display:"flex",
          height:"100%",
          transform:`translateX(${-panelIdx*100}%)`,
          transition:"transform 0.38s cubic-bezier(0.4,0,0.2,1)",
          willChange:"transform",
        }}>
          {panels.map((p,i)=>(
            <div key={i} style={{
              minWidth:"100%",
              height:"100%",
              overflowY:"auto",
              padding:"24px 16px 40px",
              display:"flex",
              flexDirection:"column",
              alignItems:"center",
              boxSizing:"border-box",
            }}>
              <div style={{width:"100%",maxWidth:680}}>
                {p.content}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Bottom nav */}
      <div style={{padding:"14px 20px",display:"flex",justifyContent:"space-between",alignItems:"center",borderTop:"1px solid rgba(255,255,255,0.06)",flexShrink:0,gap:12}}>
        <button
          onClick={prev}
          disabled={panelIdx===0}
          style={{background:"rgba(255,255,255,0.04)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,padding:"10px 20px",color:panelIdx===0?"#3a342c":"#c8b97e",cursor:panelIdx===0?"default":"pointer",fontFamily:"Georgia",fontSize:13,opacity:panelIdx===0?0.35:1,transition:"opacity 0.2s"}}
        >
          ← Prev
        </button>

        {/* Dot indicators */}
        <div style={{display:"flex",gap:7,alignItems:"center"}}>
          {panels.map((_,i)=>(
            <button
              key={i}
              onClick={()=>setPanelIdx(i)}
              style={{width:i===panelIdx?20:7,height:7,borderRadius:4,background:i===panelIdx?accent:"rgba(255,255,255,0.2)",border:"none",cursor:"pointer",padding:0,transition:"all 0.25s ease"}}
            />
          ))}
        </div>

        <button
          onClick={next}
          disabled={panelIdx===total-1}
          style={{background:panelIdx===total-1?"rgba(255,255,255,0.04)":`linear-gradient(135deg,${accent},${accent}cc)`,border:"none",borderRadius:8,padding:"10px 20px",color:panelIdx===total-1?"#3a342c":"#fff",cursor:panelIdx===total-1?"default":"pointer",fontFamily:"Georgia",fontSize:13,fontWeight:panelIdx===total-1?400:700,opacity:panelIdx===total-1?0.35:1,transition:"opacity 0.2s"}}
        >
          Next →
        </button>
      </div>
    </div>
  );
}

export default function App(){
  const [phase,setPhase]=useState("intro");
  const [playerName,setPlayerName]=useState("");
  const [answers,setAnswers]=useState({});
  const [answerTexts,setAnswerTexts]=useState({});
  const [current,setCurrent]=useState(0);
  const [result,setResult]=useState(null);
  const [animating,setAnimating]=useState(false);
  const [generating,setGenerating]=useState(false);
  const [pdfError,setPdfError]=useState(null);
  const [revealed,setRevealed]=useState(false);
  const [showCards,setShowCards]=useState(false);

  const [cycleRune,setCycleRune]=useState("ᚱ");
  const [cycleColor,setCycleColor]=useState("#C0392B");
  const [cycleCrest,setCycleCrest]=useState("RED");
  const [shuffleKey,setShuffleKey]=useState(0);
  // ── Popup / nudge states ──────────────────────────────────────────────────
  const [showMindsetPopup,setShowMindsetPopup]=useState(false); // Q1 anchor popup
  const [showSlowPopup,setShowSlowPopup]=useState(false);       // >45s on one Q
  const [showFastPopup,setShowFastPopup]=useState(false);       // 3 Qs < 12s total
  const qStartTimeRef=useRef(null);    // when current Q was shown
  const recentAnswerTimesRef=useRef([]); // timestamps of last 3 answers
  const slowTimerRef=useRef(null);     // timeout for slow nudge
  const mindsetShownRef=useRef(false); // only show mindset popup once
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const QUESTIONS=useMemo(()=>buildShuffledQuestions(),[shuffleKey]);

  // ── Google Sheets webhook URL — paste your Apps Script Web App URL here ──
  const SHEET_WEBHOOK_URL = "https://script.google.com/macros/s/AKfycbwk67aa9yjMDqGxTDlb-in0T1AaRclGzv8XD4T2WgoiyL97HnKCtJ-4aC8xSO6AJ3qR/exec";

  async function submitResult(resolvedResult, scores, topColor, myClass, dualProfile, rawAnswers, rawAnswerTexts) {
    if (!SHEET_WEBHOOK_URL || SHEET_WEBHOOK_URL === "YOUR_APPS_SCRIPT_URL_HERE") return;
    try {
      const isTieResult = resolvedResult.type === "dual" || resolvedResult.type === "shapeshifter";
      const secondColor = isTieResult ? resolvedResult.colors[1] : "";
      const secondClass = isTieResult && secondColor
        ? getClass(CLASSES[secondColor], scores[secondColor])
        : "";
      // Compute weakest color (lowest score, not primary or dual partner, score < 5)
      const _excludeWeak = new Set([topColor, ...(resolvedResult.influence||[])]);
      const _weakest = ["RED","PURPLE","BLUE","GREEN"]
        .filter(c => !_excludeWeak.has(c))
        .sort((a,b) => (scores[a]||0) - (scores[b]||0))[0];
      const _weakestScore = _weakest ? (scores[_weakest]||0) : 0;

      // ── Compute personalised result strings for sheet ──────────────────
      // Answer text string: Q00=<text>|Q01=<text>|...
      const answerTextStr = rawAnswerTexts
        ? Object.entries(rawAnswerTexts)
            .sort((a,b)=>parseInt(a[0])-parseInt(b[0]))
            .map(([i,t])=>`Q${String(parseInt(i)).padStart(2,"0")}=${(t||"").replace(/[,|]/g,"")}`)
            .join("|")
        : "";

      // Personalised strengths and price from CBCI trait map
      const DIAG_P = {Q07:10,Q09:9,Q11:9,Q03:8,Q12:8,Q06:8,Q02:7,Q10:7,Q19:7,Q00:6,Q04:6,Q08:6,Q01:5,Q13:5,Q16:5,Q17:5,Q05:4,Q14:4,Q15:4,Q18:4};
      const _sWeighted = [], _shWeighted = [];
      Object.entries(rawAnswers||{}).forEach(([qi,color])=>{
        const qk="Q"+String(parseInt(qi)).padStart(2,"0");
        const pri=DIAG_P[qk]||3;
        const trait=Q_TRAIT_MAP[qk]?.[color];
        if(trait && color===topColor){
          _sWeighted.push({s:trait.s,pri});
          _shWeighted.push({sh:trait.sh,pri});
        }
      });
      _sWeighted.sort((a,b)=>b.pri-a.pri);
      _shWeighted.sort((a,b)=>b.pri-a.pri);
      const _str1 = _sWeighted[0]?.s||"";
      const _str2 = _sWeighted[1]?.s||"";
      const _price = isTieResult&&dualProfile ? dualProfile.blindspot : (_shWeighted[0]?.sh||"");

      // Influence whispers
      const _inflColors = (resolvedResult.influence||[]);
      const _whispers = _inflColors.map(ic=>{
        const topQForColor = Object.entries(rawAnswers||{})
          .filter(([,c])=>c===ic)
          .map(([qi])=>{const qk="Q"+String(parseInt(qi)).padStart(2,"0");return{qk,pri:DIAG_P[qk]||3};})
          .sort((a,b)=>b.pri-a.pri)[0];
        return topQForColor ? (WHISPER_MAP[topQForColor.qk]?.[ic]||"") : "";
      }).filter(Boolean);

      // Clash observations
      const _clashObs = [];
      if(_weakestScore < 5 && _weakest){
        const primaryQs = Object.entries(rawAnswers||{})
          .filter(([,c])=>c===topColor)
          .map(([qi])=>{const qk="Q"+String(parseInt(qi)).padStart(2,"0");return{qk,pri:DIAG_P[qk]||3};})
          .sort((a,b)=>b.pri-a.pri);
        for(const {qk} of primaryQs){
          if(_clashObs.length>=2)break;
          const obs=FRICTION_Q_MAP[qk]?.[_weakest];
          if(obs)_clashObs.push(obs);
        }
      }

      // Abilities
      const _classData = CLASSES[topColor]?.classData;
      const _cd = _classData ? _classData[myClass] : null;
      const _abilities = _cd ? _cd.abilities : [];
      const _lockedName = _cd ? _cd.locked : "";
      const _unlockedAbs = _abilities.filter(a=>a.name!==_lockedName).map(a=>a.name);
      // Encode raw per-question answers as Q00=RED,Q01=BLUE,... for the sheet
      const answerStr = rawAnswers
        ? Object.entries(rawAnswers)
            .sort((a,b)=>parseInt(a[0])-parseInt(b[0]))
            .map(([i,c])=>`Q${String(parseInt(i)).padStart(2,"0")}=${c}`)
            .join(",")
        : "";
      const payload = {
        timestamp:    new Date().toISOString(),
        name:         playerName || "Anonymous",
        brainColor:   topColor,
        class:        myClass,
        resultType:   resolvedResult.type,
        dualTitle:    isTieResult && dualProfile ? dualProfile.label : "",
        secondColor:  secondColor,
        secondClass:  secondClass,
        scoreRED:     scores.RED,
        scorePURPLE:  scores.PURPLE,
        scoreBLUE:    scores.BLUE,
        scoreGREEN:   scores.GREEN,
        answers:       answerStr,
        answerTexts:   answerTextStr,
        influence:     (resolvedResult.influence||[]).join("+"),
        weakestColor:  (_weakestScore < 5 ? _weakest : "")||"",
        weakestScore:  _weakestScore,
        strength1:     _str1,
        strength2:     _str2,
        price:         _price,
        whispers:      _whispers.join(" | "),
        clashes:       _clashObs.join(" | "),
        abilities:     _unlockedAbs.join(", "),
        lockedAbility: _lockedName,
        quest: (() => {
          const top = _sWeighted[0];
          if (!top) return "";
          const fq = Object.entries(rawAnswers||{}).find(([qi,c]) => {
            const qk="Q"+String(parseInt(qi)).padStart(2,"0");
            return c===topColor && Q_TRAIT_MAP[qk]?.[c]?.s === top.s;
          });
          if (!fq) return "";
          const qk="Q"+String(parseInt(fq[0])).padStart(2,"0");
          return Q_QUEST_MAP[qk]?.[topColor] || "";
        })(),
      };
      await fetch(SHEET_WEBHOOK_URL, {
        method: "POST",
        mode: "no-cors",
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(payload),
      });
    } catch(e) { console.warn("Sheet submission failed:", e); }
  }

  const cycleRef=useRef(null);

  // Start cycling runes when result phase begins and not yet revealed
  useEffect(()=>{
    if(phase==="result"&&!revealed){
      cycleRef.current=setInterval(()=>{
        const pick=ALL_RUNES[Math.floor(Math.random()*ALL_RUNES.length)];
        setCycleRune(pick.r);
        setCycleColor(pick.c);
        const crestColors=["RED","PURPLE","BLUE","GREEN"];
        setCycleCrest(crestColors[Math.floor(Math.random()*crestColors.length)]);
      },120);
    } else {
      if(cycleRef.current){clearInterval(cycleRef.current);cycleRef.current=null;}
    }
    return()=>{if(cycleRef.current){clearInterval(cycleRef.current);}};
  },[phase,revealed]);

  function scrollTop(){window.scrollTo({top:0,behavior:"instant"});}

  function selectAnswer(color,text){
    if(animating)return;

    // ── Timing checks ────────────────────────────────────────────────────
    const now = Date.now();
    // Clear any pending slow-nudge timer
    if(slowTimerRef.current){clearTimeout(slowTimerRef.current);slowTimerRef.current=null;}
    // Record this answer timestamp for fast-detection (keep last 3)
    recentAnswerTimesRef.current = [...recentAnswerTimesRef.current, now].slice(-3);
    // Fast check: if 3 answers happened in under 12 seconds, show fast nudge
    if(recentAnswerTimesRef.current.length===3){
      const span = recentAnswerTimesRef.current[2] - recentAnswerTimesRef.current[0];
      if(span < 12000 && !showFastPopup){setShowFastPopup(true);}
    }

    const newAnswers={...answers,[current]:color};
    const newAnswerTexts={...answerTexts,[current]:text||""};
    setAnswers(newAnswers);
    setAnswerTexts(newAnswerTexts);
    setAnimating(true);
    setTimeout(()=>{
      setAnimating(false);
      if(current<QUESTIONS.length-1){
        setCurrent(current+1);
        scrollTop();
        // Start slow-nudge timer for next Q (45s)
        qStartTimeRef.current = Date.now();
        slowTimerRef.current = setTimeout(()=>{
          setShowSlowPopup(true);
          slowTimerRef.current = null;
        }, 45000);
      } else{
        const fs={RED:0,PURPLE:0,BLUE:0,GREEN:0};
        Object.values(newAnswers).forEach(c=>{fs[c]++;});
        const resolved=resolveResult(fs);
        setResult({scores:fs,topColor:resolved.colors[0],resolved,rawAnswers:{...newAnswers},rawAnswerTexts:{...newAnswerTexts}});
        setPhase("result");
        scrollTop();
      }
    },320);
  }

  function reset(){
    if(slowTimerRef.current){clearTimeout(slowTimerRef.current);slowTimerRef.current=null;}
    recentAnswerTimesRef.current=[];
    mindsetShownRef.current=false;
    setShowMindsetPopup(false);setShowSlowPopup(false);setShowFastPopup(false);
    setPhase("intro");setAnswers({});setAnswerTexts({});setCurrent(0);setResult(null);setRevealed(false);setCycleRune("ᚱ");setCycleColor("#C0392B");setShuffleKey(k=>k+1);scrollTop();}

  async function handleDownloadPDF(){
    if(!result)return;
    setGenerating(true);
    setPdfError(null);
    try{
      const resolved=result.resolved||{type:"single",colors:[result.topColor]};
      const isDual=resolved.type==="tie"||resolved.type==="split"||(resolved.type==="dual")||false;

      if(isDual){
        // Dual: get DUAL_PROFILES data which has abilities, strengths, etc directly
        const dualProfile=getDualProfile(resolved);
        const c1=resolved.colors[0]; const c2=resolved.colors[1]||c1;
        const label1=getClass(CLASSES[c1],result.scores[c1]);
        const label2=c2!==c1?getClass(CLASSES[c2],result.scores[c2]):"";
        const label=label2?`${label1} / ${label2}`:label1;
        const pdfData={
          color: dualProfile?.color1||CLASSES[c1].color,
          label: dualProfile?.label||label,
          strengths: dualProfile?.strengths||[],
          blindspot: dualProfile?.blindspot||dualProfile?.blindPrice||"",
          quest: dualProfile?.quest||"",
          abilities: dualProfile?.abilities||[],
          locked: null, // dual locked handled via ab.locked===true
        };
        await generateCharacterSheetPDF(playerName,c1,label,result.scores,pdfData);
      } else {
        // Single class
        const data=CLASSES[result.topColor];
        const myScore=result.scores[result.topColor];
        const myClass=getClass(data,myScore);
        const cd=data.classData?.[myClass];
        const pdfData={
          color: data.color,
          label: data.label,
          strengths: cd?.strengths||[],
          blindspot: cd?.blindspot||cd?.blindPrice||"",
          quest: cd?.quest||"",
          abilities: cd?.abilities||[],
          locked: cd?.locked||null,
          classData: null, // already resolved
        };
        await generateCharacterSheetPDF(playerName,result.topColor,myClass,result.scores,pdfData);
      }
    }catch(e){console.error("PDF error:",e);setPdfError("PDF generation failed — please try again or use the Print option.");}finally{setGenerating(false);}
  }

  const progress=(Object.keys(answers).length/QUESTIONS.length)*100;
  const q=QUESTIONS[current];
  const t=Q_THEMES[current]||Q_THEMES[0];
  const selectedColor=answers[current];

  // ── Card Reveal Screen ──────────────────────────────────────────────────
  if(showCards&&result){
    return(
      <CardRevealScreen
        result={result}
        playerName={playerName}
        onClose={()=>setShowCards(false)}
        reset={()=>{setShowCards(false);reset();}}
        onDownloadPDF={handleDownloadPDF}
        generating={generating}
        pdfError={pdfError}
      />
    );
  }

  return(
    <div style={{minHeight:"100vh",background:"#080810",fontFamily:"'Georgia',serif",color:"#e8e4d9",display:"flex",flexDirection:"column",alignItems:"center",padding:"0 16px 60px"}}>

      {/* Header */}
      <div style={{width:"100%",maxWidth:720,padding:"28px 0 16px"}}>
        <div style={{textAlign:"center",letterSpacing:"0.3em",fontSize:11,color:"#b7950b",marginBottom:6,textTransform:"uppercase"}}>Hero's Journey Workshop</div>
        <h1 style={{margin:0,fontSize:"clamp(22px,5vw,36px)",fontWeight:700,textAlign:"center",color:"#f0ebe0",letterSpacing:"0.05em"}}>✦ The Hero's Ink Test ✦</h1>
        <p style={{textAlign:"center",color:"#8a7f6e",fontSize:14,margin:"6px 0 0",fontStyle:"italic"}}>Discover your Leadership Class in 10 minutes</p>
      </div>

      {/* INTRO */}
      {phase==="intro"&&(
        <div style={{maxWidth:620,width:"100%",animation:"fadeIn 0.6s ease"}}>
          <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@keyframes glow{0%,100%{box-shadow:0 0 20px rgba(183,149,11,0.2)}50%{box-shadow:0 0 40px rgba(183,149,11,0.4)}}`}</style>
          <div style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(183,149,11,0.25)",borderRadius:16,padding:"32px 36px",marginBottom:22}}>
            <p style={{fontSize:15,lineHeight:1.85,color:"#c9c1b0",margin:"0 0 16px"}}>Every adventurer begins with a single truth: <em>knowing thyself</em>. This test will reveal your natural leadership style — your Brain Color — and the class that matches it.</p>
            <p style={{fontSize:15,lineHeight:1.85,color:"#c9c1b0",margin:"0 0 16px"}}><strong style={{color:"#f0ebe0"}}>20 questions.</strong> Pick the answer that feels most natural — not who you want to be, but who you already are.</p>
            <div style={{marginBottom:0}}>
              <label style={{display:"block",fontSize:12,color:"#8a7f6e",letterSpacing:"0.15em",textTransform:"uppercase",marginBottom:8}}>Your Name (optional — for your character sheet)</label>
              <input value={playerName} onChange={e=>setPlayerName(e.target.value)} placeholder="Enter your name..." style={{width:"100%",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(183,149,11,0.3)",borderRadius:8,padding:"10px 14px",color:"#f0ebe0",fontSize:14,fontFamily:"Georgia,serif",outline:"none",boxSizing:"border-box"}}/>
            </div>
          </div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap",marginBottom:28}}>
            {KEYS.map(k=>(
              <div key={k} style={{flex:"1 1 130px",background:CLASSES[k].light+"15",border:`1px solid ${CLASSES[k].color}44`,borderRadius:10,padding:"12px 14px",display:"flex",flexDirection:"column",alignItems:"center",textAlign:"center"}}>
                <img src={CREST_MAP[k]} alt={k} style={{width:52,height:52,objectFit:"contain",marginBottom:6,filter:"drop-shadow(0 2px 6px rgba(0,0,0,0.5))"}}/>
                <div style={{fontSize:11,fontWeight:700,color:CLASSES[k].color,letterSpacing:"0.1em"}}>{CLASSES[k].label}</div>
                <div style={{fontSize:10,color:"#8a7f6e",marginTop:3}}>{CLASSES[k].classes.join(" · ")}</div>
              </div>
            ))}
          </div>
          <button onClick={()=>{setPhase("quiz");
          if(!mindsetShownRef.current){setShowMindsetPopup(true);mindsetShownRef.current=true;}
          // Start slow timer for Q1
          qStartTimeRef.current=Date.now();
          if(slowTimerRef.current)clearTimeout(slowTimerRef.current);
          slowTimerRef.current=setTimeout(()=>{setShowSlowPopup(true);slowTimerRef.current=null;},45000);
          scrollTop();}} style={{width:"100%",padding:"17px",background:"linear-gradient(135deg,#b7950b,#d4a017)",border:"none",borderRadius:10,color:"#0d0d12",fontSize:16,fontWeight:700,fontFamily:"Georgia,serif",letterSpacing:"0.08em",cursor:"pointer",animation:"glow 3s ease infinite"}}>
            Begin the Test ✦
          </button>
        </div>
      )}

      {/* QUIZ */}
      {phase==="quiz"&&q&&(
        <div style={{maxWidth:660,width:"100%",animation:"fadeIn 0.35s ease"}}>

          {/* ── MINDSET POPUP — shown once at start of quiz ── */}
          {showMindsetPopup&&(
            <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.82)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}>
              <div style={{background:"#1a1020",border:"1px solid rgba(183,149,11,0.45)",borderRadius:16,padding:"32px 28px",maxWidth:420,width:"100%",textAlign:"center"}}>
                <div style={{fontSize:28,marginBottom:12}}>⚔</div>
                <p style={{fontSize:15,fontWeight:"bold",color:"#e8e4d9",fontFamily:"Georgia,serif",marginBottom:14,lineHeight:1.5}}>Answer as the hero you are — not the one you want to be.</p>
                <p style={{fontSize:13,color:"#9a8f78",fontFamily:"Calibri,sans-serif",lineHeight:1.7,marginBottom:20}}>This quest isn't about who you're striving to become. It's about who you are right now — your real habits, your actual instincts, the choices you genuinely make under pressure.<br/><br/>The road to becoming a legend starts with seeing yourself clearly. Answer as you <em>are</em>, not as you wish you were.</p>
                <button onClick={()=>setShowMindsetPopup(false)} style={{background:"linear-gradient(135deg,#b7950b,#d4ac0d)",border:"none",borderRadius:10,padding:"12px 32px",color:"#0d0d12",fontWeight:"bold",fontSize:14,cursor:"pointer",fontFamily:"Georgia,serif",letterSpacing:"0.05em"}}>I'm ready ✦</button>
              </div>
            </div>
          )}

          {/* ── SLOW NUDGE POPUP — triggered after 45s on one Q ── */}
          {showSlowPopup&&(
            <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.75)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}>
              <div style={{background:"#0f1420",border:"1px solid rgba(100,120,200,0.4)",borderRadius:16,padding:"28px 24px",maxWidth:380,width:"100%",textAlign:"center"}}>
                <div style={{fontSize:24,marginBottom:10}}>🜂</div>
                <p style={{fontSize:14,fontWeight:"bold",color:"#c9d4f0",fontFamily:"Georgia,serif",marginBottom:12,lineHeight:1.5}}>Still deciding?</p>
                <p style={{fontSize:13,color:"#7a8aaa",fontFamily:"Calibri,sans-serif",lineHeight:1.7,marginBottom:18}}>There's no right answer — only your honest one. Trust your first instinct. What would you actually do, not what you think you should do?</p>
                <button onClick={()=>setShowSlowPopup(false)} style={{background:"rgba(100,120,200,0.2)",border:"1px solid rgba(100,120,200,0.5)",borderRadius:10,padding:"10px 28px",color:"#c9d4f0",fontSize:13,cursor:"pointer",fontFamily:"Georgia,serif"}}>Got it</button>
              </div>
            </div>
          )}

          {/* ── FAST NUDGE POPUP — triggered if 3 Qs answered in < 12s ── */}
          {showFastPopup&&(
            <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.75)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}>
              <div style={{background:"#140f0f",border:"1px solid rgba(192,57,43,0.4)",borderRadius:16,padding:"28px 24px",maxWidth:380,width:"100%",textAlign:"center"}}>
                <div style={{fontSize:24,marginBottom:10}}>⚠</div>
                <p style={{fontSize:14,fontWeight:"bold",color:"#f0c9c0",fontFamily:"Georgia,serif",marginBottom:12,lineHeight:1.5}}>Hold on, adventurer.</p>
                <p style={{fontSize:13,color:"#a07060",fontFamily:"Calibri,sans-serif",lineHeight:1.7,marginBottom:18}}>Each question in this test maps to a real dimension of how you lead and think. Your results are only as accurate as your attention.<br/><br/>Take a breath. Read each one properly.</p>
                <button onClick={()=>{setShowFastPopup(false);recentAnswerTimesRef.current=[];}} style={{background:"rgba(192,57,43,0.2)",border:"1px solid rgba(192,57,43,0.5)",borderRadius:10,padding:"10px 28px",color:"#f0c9c0",fontSize:13,cursor:"pointer",fontFamily:"Georgia,serif"}}>I'll slow down</button>
              </div>
            </div>
          )}
          <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}`}</style>
          <div style={{marginBottom:18}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:12,color:t.muted,marginBottom:7}}>
              <span>Question {current+1} of {QUESTIONS.length}</span>
              <span style={{color:t.accent,fontWeight:"bold"}}>{Object.keys(answers).length} XP gained</span>
            </div>
            <div style={{height:3,background:"rgba(255,255,255,0.07)",borderRadius:2}}>
              <div style={{height:"100%",width:`${progress}%`,background:t.progress,borderRadius:2,transition:"width 0.4s ease"}}/>
            </div>
          </div>
          <div style={{width:"100%",borderRadius:14,overflow:"hidden",marginBottom:14,border:`1px solid ${t.border}`,boxShadow:`0 0 40px ${t.accent}18`}}>
            <img src={IMGS[q.img]} alt="" style={{width:"100%",height:"auto",display:"block"}}/>
          </div>
          <div style={{position:"relative",overflow:"hidden",background:"#b8832a",border:"1px solid #8a5c18",borderRadius:10,padding:"20px 24px 16px",boxShadow:"inset 0 1px 0 rgba(255,220,120,0.3), 0 3px 14px rgba(0,0,0,0.5)"}}>
            
            
            <img src={ASSETS.PARCHMENT} alt="" style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",objectPosition:"center",pointerEvents:"none",zIndex:0}}/>
            <div style={{position:"absolute",inset:0,background:"rgba(220,175,90,0.45)",borderRadius:10,pointerEvents:"none",zIndex:1}}/>
            <p style={{fontSize:"clamp(15px,2.5vw,17px)",lineHeight:1.78,color:"#1a0d00",margin:0,fontStyle:"italic",textAlign:"center",position:"relative",zIndex:2,textShadow:"0 0 8px rgba(255,240,200,0.9), 0 1px 3px rgba(255,235,180,0.8)"}}>  "{q.q}"</p>
          </div>
          {q.footnote?(
            <div style={{padding:"6px 16px 10px",background:"rgba(180,120,40,0.07)",borderLeft:`2px solid ${t.border}`,marginTop:2,borderRadius:"0 0 8px 8px"}}>
              <p style={{fontSize:12,lineHeight:1.65,color:"#7a5c30",margin:0,fontFamily:"Calibri,sans-serif"}}>{q.footnote}</p>
            </div>
          ):<div style={{height:11}}/>}
          <div style={{background:t.mindsetBg,border:`1px solid ${t.mindsetBorder}`,borderRadius:10,padding:"11px 15px",marginTop:14,display:"flex",gap:10,alignItems:"flex-start"}}>
            <span style={{fontSize:14,color:t.accent,flexShrink:0,marginTop:1}}>🧭</span>
            <p style={{fontSize:13,lineHeight:1.65,color:t.muted,margin:0,fontStyle:"italic"}}>{q.mindset}</p>
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:9,marginTop:2}}>
            {q.options.map((opt,i)=>{
              const isSel=selectedColor===opt.color;
              return(
                <button key={i} onClick={()=>selectAnswer(opt.color,opt.text)} style={{background:isSel?t.optSel:"rgba(255,255,255,0.03)",border:isSel?`1px solid ${t.optSelBorder}`:`1px solid rgba(255,255,255,0.09)`,borderRadius:10,padding:"13px 16px",cursor:"pointer",textAlign:"left",display:"flex",alignItems:"center",gap:12,transition:"all 0.18s ease",opacity:animating&&!isSel?0.5:1}}>
                  <span style={{minWidth:25,height:25,borderRadius:"50%",background:isSel?t.accent:"rgba(255,255,255,0.08)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:700,color:isSel?"#0d0d12":t.muted,flexShrink:0}}>{LABELS[i]}</span>
                  <span style={{fontSize:14,lineHeight:1.6,color:isSel?t.text:"#c9c1b0",fontFamily:"Calibri,sans-serif"}}>{opt.text}</span>
                </button>
              );
            })}
          </div>
          <div style={{display:"flex",justifyContent:"space-between",marginTop:14}}>
            <button onClick={()=>{if(current>0){setCurrent(current-1);scrollTop();}}} disabled={current===0} style={{background:"none",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,padding:"9px 18px",color:current===0?"#333":t.muted,cursor:current===0?"default":"pointer",fontFamily:"Georgia",fontSize:13}}>← Back</button>
            {Object.keys(answers).length===QUESTIONS.length&&current===QUESTIONS.length-1&&(
              <button onClick={()=>{const fs={RED:0,PURPLE:0,BLUE:0,GREEN:0};Object.values(answers).forEach(c=>{fs[c]++;});const resolved=resolveResult(fs);setResult({scores:fs,topColor:resolved.colors[0],resolved,rawAnswers:{...answers}});setPhase("result");}} style={{background:`linear-gradient(135deg,${t.accent},${t.accent}cc)`,border:"none",borderRadius:8,padding:"9px 22px",color:"#0d0d12",fontWeight:700,fontFamily:"Georgia",fontSize:14,cursor:"pointer",letterSpacing:"0.05em"}}>Reveal My Class ✦</button>
            )}
          </div>
        </div>
      )}

      {/* RESULT */}
      {phase==="result"&&result&&(()=>{
        const resolved=result.resolved||{type:"single",colors:[result.topColor],influence:[]};
        const isTie=resolved.type==="dual"||resolved.type==="shapeshifter";
        const influence=(!isTie&&resolved.influence&&resolved.influence.length>0)?resolved.influence:[];
        const rawAnswers=result.rawAnswers||{};
        // Always build insight for friction — pass empty influence for dual results
        const insight=buildInsight(rawAnswers,result.scores,result.topColor,isTie?[]:influence,QUESTIONS);
        const dualProfile=isTie?getDualProfile(resolved):null;
        const data=CLASSES[result.topColor];
        const myScore=result.scores[result.topColor];
        const myClass=getClass(data,myScore);
        const cd=data.classData?data.classData[myClass]:null;
        const sorted=Object.entries(result.scores).sort((a,b)=>b[1]-a[1]);
        const displayStrengths=isTie&&dualProfile?dualProfile.strengths:(cd?cd.strengths:data.strengths||[]);
        const displayBlindspot=isTie&&dualProfile?dualProfile.blindspot:(cd?cd.blindspot:data.blindspot||"");
        const displayQuest=isTie&&dualProfile?dualProfile.quest:(cd?cd.quest:data.quest||"");
        // Score each ability by how many of its Q indices the user answered as primary color
        const rawAns = result.rawAnswers || {};
        const primaryColorAnswers = new Set(
          Object.entries(rawAns)
            .filter(([,c]) => c === result.topColor)
            .map(([i]) => parseInt(i))
        );
        const scoreAbility = (ab) => {
          const qs = ABILITY_Q_MAP[ab.name] || [];
          return qs.filter(q => primaryColorAnswers.has(q)).length;
        };
        const baseAbilities = isTie&&dualProfile ? dualProfile.abilities : (cd?cd.abilities:[]);
        // Reorder: locked ability always last, unlocked sorted by resonance score
        const singleLockedName = cd ? cd.locked : null;
        const isAbilityLocked = (ab) => isTie&&dualProfile ? ab.locked : ab.name===singleLockedName;
        const displayAbilities = [
          ...baseAbilities.filter(ab=>!isAbilityLocked(ab)).sort((a,b)=>scoreAbility(b)-scoreAbility(a)),
          ...baseAbilities.filter(ab=>isAbilityLocked(ab)),
        ];
        return(
          <div style={{maxWidth:680,width:"100%",animation:"fadeIn 0.8s ease"}}>
            <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}} @keyframes revealIn{from{opacity:0;transform:scale(0.96) translateY(24px)}to{opacity:1;transform:none}} @keyframes runeReveal{0%{opacity:0;transform:scale(0.5) rotate(-20deg)}60%{transform:scale(1.3) rotate(5deg)}100%{opacity:1;transform:scale(1) rotate(0deg)}} @keyframes runeFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}} @keyframes glow{0%,100%{box-shadow:0 0 20px rgba(183,149,11,0.3)}50%{box-shadow:0 0 50px rgba(183,149,11,0.6)}}`}</style>

            {!revealed&&(
              <div style={{textAlign:"center",padding:"40px 20px",animation:"fadeIn 0.6s ease"}}>
                <div style={{position:"relative",width:100,height:100,margin:"0 auto 16px",display:"flex",alignItems:"center",justifyContent:"center"}}>
                  <img src={CREST_MAP[cycleCrest]} alt="" style={{position:"absolute",width:90,height:90,objectFit:"contain",opacity:0.18,filter:`blur(1px) drop-shadow(0 0 20px ${cycleColor})`,transition:"opacity 0.1s ease"}}/>
                  <div style={{fontSize:64,animation:"runeFloat 2s ease-in-out infinite",color:cycleColor,transition:"color 0.08s ease",textShadow:`0 0 30px ${cycleColor}88`,position:"relative",zIndex:1}}>{cycleRune}</div>
                </div>
                <div style={{fontSize:11,letterSpacing:"0.3em",color:"#b7950b",textTransform:"uppercase",marginBottom:8}}>Your class has been determined</div>
                <h2 style={{fontSize:"clamp(20px,4vw,28px)",margin:"0 0 12px",color:"#f0ebe0"}}>Are you ready to see who you are?</h2>
                <p style={{fontSize:14,color:"#8a7f6e",fontStyle:"italic",margin:"0 0 32px",lineHeight:1.7}}>Twenty questions. Twenty choices. One truth.</p>
                <button onClick={()=>{
                  setRevealed(true);
                  const res=result.resolved||{type:"single",colors:[result.topColor],influence:[]};
                  const d=CLASSES[result.topColor];
                  const sc=result.scores[result.topColor];
                  const mc=getClass(d,sc);
                  const dp=res.type==="dual"||res.type==="shapeshifter"?getDualProfile(res):null;
                  submitResult(res,result.scores,result.topColor,mc,dp,result.rawAnswers||{},result.rawAnswerTexts||{});
                }} style={{background:`linear-gradient(135deg,${data.color},${data.color}cc)`,border:"none",borderRadius:12,padding:"16px 40px",color:"#fff",fontSize:17,fontWeight:700,fontFamily:"Georgia,serif",letterSpacing:"0.08em",cursor:"pointer",boxShadow:`0 0 40px ${data.color}55`,animation:"glow 2s ease infinite"}}>
                  Reveal My Class ✦
                </button>
              </div>
            )}
            {revealed&&(
            <div style={{animation:"revealIn 0.7s cubic-bezier(0.16,1,0.3,1)"}}>
            {/* Class reveal */}
            {!isTie&&(
            <div style={{background:`linear-gradient(135deg,${data.color}22,${data.color}08)`,border:`1px solid ${data.color}55`,borderRadius:20,padding:"34px 30px",marginBottom:18,textAlign:"center",boxShadow:`0 0 60px ${data.glow}`}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:16,marginBottom:10}}>
                <img src={CREST_MAP[result.topColor]} alt="" style={{width:64,height:64,objectFit:"contain",animation:"runeReveal 0.5s cubic-bezier(0.34,1.56,0.64,1)",filter:`drop-shadow(0 0 14px ${data.color}88)`}}/>
                <div style={{textAlign:"left"}}>
                  <div style={{fontSize:36,lineHeight:1,animation:"runeReveal 0.4s cubic-bezier(0.34,1.56,0.64,1)"}}>{data.rune}</div>
                  <div style={{fontSize:10,letterSpacing:"0.3em",color:data.color,textTransform:"uppercase",marginTop:4}}>{data.label}</div>
                </div>
              </div>
              <h2 style={{fontSize:"clamp(26px,6vw,42px)",margin:"0 0 8px",color:"#f0ebe0",letterSpacing:"0.05em"}}>{myClass}</h2>
              <p style={{fontSize:14,color:"#8a7f6e",fontStyle:"italic",margin:"0 0 10px"}}>"{data.flavor}"</p>
              {!isTie&&insight&&(
                <div style={{background:"rgba(255,255,255,0.04)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:12,padding:"14px 18px",margin:"10px 0",textAlign:"left"}}>
                  <p style={{fontSize:13,lineHeight:1.75,color:"#e8e4d9",margin:"0 0 8px",fontFamily:"Georgia,serif",fontStyle:"italic"}}>{insight.opening}</p>
                  {insight.primaryDetail&&<p style={{fontSize:13,lineHeight:1.75,color:"#c9c1b0",margin:"0 0 8px",fontFamily:"Calibri,sans-serif"}}>{insight.primaryDetail}</p>}
                  {insight.influenceSentences.length>0&&(
                    <div style={{borderTop:"1px solid rgba(255,255,255,0.08)",paddingTop:8,marginTop:4}}>
                      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:6}}>
                        {influence.map(c=>(
                          <span key={c} style={{display:"inline-flex",alignItems:"center",gap:3,background:CLASSES[c].color+"22",border:`1px solid ${CLASSES[c].color}44`,borderRadius:20,padding:"2px 8px"}}>
                            <img src={CREST_MAP[c]} alt={c} style={{width:12,height:12,objectFit:"contain"}}/>
                            <span style={{fontSize:9,fontWeight:700,color:CLASSES[c].color,letterSpacing:"0.1em"}}>{CLASSES[c].label}</span>
                          </span>
                        ))}
                      </div>
                      {insight.influenceSentences.map((s,i)=>(
                        <p key={i} style={{fontSize:12,lineHeight:1.7,color:"#a09880",margin:"0 0 4px",fontFamily:"Calibri,sans-serif"}}>{s}</p>
                      ))}
                    </div>
                  )}
                </div>
              )}
              {playerName&&<p style={{fontSize:13,color:data.color,margin:0}}>Your class is set, <strong>{playerName}</strong>. Your quest begins now.</p>}
            </div>
            )}
            {isTie&&dualProfile&&(
            <div style={{background:`linear-gradient(135deg,${dualProfile.color1}18,${dualProfile.color2}12)`,border:`1px solid ${dualProfile.color1}44`,borderRadius:20,padding:"34px 30px",marginBottom:18,textAlign:"center"}}>
              <div style={{fontSize:38,marginBottom:8,letterSpacing:"0.3em"}}>
                <span style={{color:dualProfile.color1}}>{CLASSES[resolved.colors[0]].rune}</span>
                <span style={{color:"#555",fontSize:24,margin:"0 6px"}}>·</span>
                <span style={{color:dualProfile.color2}}>
                  {CLASSES[resolved.colors[1]].rune}
                </span>
              </div>
              <div style={{fontSize:10,letterSpacing:"0.2em",textTransform:"uppercase",marginBottom:4,display:"flex",justifyContent:"center",gap:8,flexWrap:"wrap"}}>
                {resolved.type==="shapeshifter"
                  ?["RED","PURPLE","BLUE","GREEN"].map(c=>(<span key={c} style={{color:CLASSES[c].color}}>{CLASSES[c].label}</span>))
                  :[resolved.colors[0],resolved.colors[1]].map(c=>(<span key={c} style={{color:CLASSES[c].color}}>{CLASSES[c].label}</span>))
                }
              </div>
              <h2 style={{fontSize:"clamp(22px,4.5vw,34px)",margin:"4px 0 4px",color:"#f0ebe0",letterSpacing:"0.04em"}}>
                {myClass} / {getClass(CLASSES[resolved.colors[1]],result.scores[resolved.colors[1]])}
              </h2>
              <p style={{fontSize:13,letterSpacing:"0.15em",color:"#b7950b",textTransform:"uppercase",margin:"0 0 10px",fontStyle:"normal"}}>— {dualProfile.label} —</p>
              <p style={{fontSize:13,color:"#8a7f6e",fontStyle:"italic",margin:"0 0 10px",lineHeight:1.6}}>"{dualProfile.flavor}"</p>
              {playerName&&<p style={{fontSize:13,color:"#b7950b",margin:0}}>Your path is your own, <strong>{playerName}</strong>.</p>}
            </div>
            )}

            {/* Score breakdown */}
            <div style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:14,padding:"18px 22px",marginBottom:18}}>
              <div style={{fontSize:11,letterSpacing:"0.2em",color:"#8a7f6e",textTransform:"uppercase",marginBottom:12}}>Score Breakdown</div>
              {sorted.map(([color,score])=>(
                <div key={color} style={{display:"flex",alignItems:"center",gap:12,marginBottom:9}}>
                  <div style={{display:"flex",alignItems:"center",gap:6,width:72}}>
                    <img src={CREST_MAP[color]} alt={color} style={{width:20,height:20,objectFit:"contain",opacity:0.85}}/>
                    <span style={{fontSize:10,fontWeight:700,color:CLASSES[color].color,letterSpacing:"0.08em"}}>{color}</span>
                  </div>
                  <div style={{flex:1,height:7,background:"rgba(255,255,255,0.06)",borderRadius:4,overflow:"hidden"}}>
                    <div style={{height:"100%",width:`${(score/20)*100}%`,background:CLASSES[color].color,borderRadius:4,transition:"width 1s ease"}}/>
                  </div>
                  <div style={{width:22,fontSize:13,color:"#c9c1b0",textAlign:"right"}}>{score}</div>
                </div>
              ))}
            </div>

            {/* Strengths & Blindspot */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:18,alignItems:"start"}}>
              <div style={{background:`${data.color}12`,border:`1px solid ${data.color}33`,borderRadius:12,padding:"18px 16px"}}>
                <div style={{fontSize:11,letterSpacing:"0.2em",color:isTie?"#b7950b":data.color,textTransform:"uppercase",marginBottom:10}}>⚔ Strengths</div>
                {(insight&&insight.personalisedStrengths&&insight.personalisedStrengths.length>0
                  ?insight.personalisedStrengths
                  :displayStrengths
                ).map((s,i)=><p key={i} style={{fontSize:13,lineHeight:1.65,color:"#c9c1b0",margin:"0 0 9px",fontFamily:"Calibri,sans-serif"}}>• {s}</p>)}
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:10}}>
                <div style={{background:"rgba(192,57,43,0.08)",border:"1px solid rgba(192,57,43,0.25)",borderRadius:12,padding:"18px 16px",minHeight:0,overflow:"visible"}}>
                  <div style={{fontSize:11,letterSpacing:"0.2em",color:"#C0392B",textTransform:"uppercase",marginBottom:10}}>⚠ The Price</div>
                  <p style={{fontSize:13,lineHeight:1.65,color:"#c9c1b0",margin:"0 0 6px",fontFamily:"Calibri,sans-serif"}}>
                    {isTie?displayBlindspot:(insight&&insight.personalisedBlindspot?insight.personalisedBlindspot:displayBlindspot)}
                  </p>
                  {insight&&insight.inflBlindspots&&insight.inflBlindspots.map((b,i)=>(
                    <p key={i} style={{fontSize:11,lineHeight:1.6,color:"#9a8060",margin:"8px 0 0",fontFamily:"Calibri,sans-serif",fontStyle:"italic",borderTop:"1px solid rgba(150,100,60,0.15)",paddingTop:6,overflowWrap:"break-word",wordBreak:"break-word"}}>{b}</p>
                  ))}
                </div>
              </div>

            </div>

            {/* Friction Section — above class abilities */}
            {insight&&insight.frictionObservations&&insight.frictionObservations.length>0&&(
              <div style={{background:"rgba(80,40,20,0.12)",border:"1px solid rgba(150,80,40,0.28)",borderRadius:12,padding:"18px 18px",marginBottom:18}}>
                <div style={{fontSize:11,letterSpacing:"0.18em",color:"#b06040",textTransform:"uppercase",marginBottom:12}}>⚔ Who You May Clash With</div>
                {insight.frictionObservations.length===1
                  ? <p style={{fontSize:13,lineHeight:1.75,color:"#c9b8a0",margin:0,fontFamily:"Calibri,sans-serif",overflowWrap:"break-word",wordBreak:"break-word"}}>{insight.frictionObservations[0]}</p>
                  : insight.frictionObservations.length===2
                  ? (<>
                      <p style={{fontSize:13,lineHeight:1.75,color:"#c9b8a0",margin:"0 0 8px",fontFamily:"Calibri,sans-serif",overflowWrap:"break-word",wordBreak:"break-word"}}>{insight.frictionObservations[0]}</p>
                      <p style={{fontSize:11,lineHeight:1.5,color:"#8a6855",margin:"0 0 8px",fontFamily:"Calibri,sans-serif",fontStyle:"italic"}}>This same tendency can also show up as:</p>
                      <p style={{fontSize:13,lineHeight:1.75,color:"#c9b8a0",margin:0,fontFamily:"Calibri,sans-serif",overflowWrap:"break-word",wordBreak:"break-word"}}>{insight.frictionObservations[1]}</p>
                    </>)
                  : null
                }
                <p style={{fontSize:10,color:"#8a6040",marginTop:12,fontStyle:"italic",fontFamily:"Calibri,sans-serif",borderTop:"1px solid rgba(150,80,40,0.2)",paddingTop:8}}>
                  {`This reflects the ${ CLASSES[insight.weakestColor]?.label || insight.weakestColor} thinking style — the one furthest from your natural instincts.`}
                </p>
              </div>
            )}
            {/* Abilities */}
            <div style={{marginBottom:18}}>
              <div style={{fontSize:11,letterSpacing:"0.2em",color:"#8a7f6e",textTransform:"uppercase",marginBottom:12}}>Class Abilities</div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                {displayAbilities.map((ab,i)=>{
                  const isLocked=isAbilityLocked(ab);
                  // Dual abilities have lean1/lean2 — use diagonal gradient between their colors
                  const COLOR_HEX={RED:"#C0392B",PURPLE:"#6C3483",BLUE:"#1A5276",GREEN:"#1E8449"};
                  const isDualAb = !isLocked && ab.lean1 && ab.lean2;
                  const lean1hex = isDualAb ? COLOR_HEX[ab.lean1]||dualProfile?.color1||data.color : null;
                  const lean2hex = isDualAb ? COLOR_HEX[ab.lean2]||dualProfile?.color2||data.color : null;
                  const abBg = isLocked
                    ? "rgba(20,18,18,0.85)"
                    : isDualAb
                    ? `linear-gradient(135deg, ${lean1hex}18 0%, ${lean2hex}12 100%)`
                    : `${isTie&&dualProfile?dualProfile.color1:data.color}10`;
                  const abBorder = isLocked
                    ? "1px solid rgba(80,70,70,0.3)"
                    : isDualAb
                    ? `1px solid ${lean1hex}40`
                    : `1px solid ${isTie&&dualProfile?dualProfile.color1:data.color}30`;
                  return(
                    <div key={i} style={{background:abBg,border:abBorder,borderRadius:10,padding:"14px 14px",position:"relative",overflow:"hidden"}}>
                      {isLocked&&<div style={{position:"absolute",inset:0,background:"rgba(10,8,20,0.6)",backdropFilter:"blur(2px)",borderRadius:10,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:4}}>
                        <span style={{fontSize:18}}>🔒</span>
                        <span style={{fontSize:10,color:"#8a7a7a",textAlign:"center",lineHeight:1.5,padding:"0 4px"}}>Unlock this ability by joining<br/>the Hero's Journey Workshop</span>
                      </div>}
                      <div style={{fontSize:12,fontWeight:700,color:isLocked?"#6a6060":isDualAb?lean1hex:(isTie&&dualProfile?dualProfile.color1:data.color),marginBottom:4}}>{ab.name}</div>
                      <div style={{fontSize:11,color:isLocked?"#3a2a5a":"#b0a890",lineHeight:1.5,marginBottom:4,fontFamily:"Calibri,sans-serif"}}>{ab.desc}</div>
                      <div style={{fontSize:10,marginTop:2,display:"flex",alignItems:"center",gap:6}}>
                        <span style={{color:isLocked?"#2a1a4a":"#7a6a50",fontFamily:"Calibri,sans-serif",fontStyle:"italic"}}>EQ: {ab.eq}</span>
                        {isDualAb&&(
                          <span style={{display:"inline-flex",gap:3,marginLeft:"auto"}}>
                            <span style={{width:7,height:7,borderRadius:"50%",background:lean1hex,display:"inline-block",opacity:0.85}}/>
                            <span style={{width:7,height:7,borderRadius:"50%",background:lean2hex,display:"inline-block",opacity:0.85}}/>
                          </span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Quest */}
            <div style={{background:"rgba(183,149,11,0.1)",border:"1px solid rgba(183,149,11,0.35)",borderRadius:12,padding:"18px 22px",marginBottom:18}}>
              <div style={{fontSize:11,letterSpacing:"0.2em",color:"#b7950b",textTransform:"uppercase",marginBottom:8}}>✦ Your First Quest</div>
              <p style={{fontSize:14,lineHeight:1.75,color:"#e8e4d9",margin:0,fontFamily:"Calibri,sans-serif"}}>{insight&&insight.personalisedQuest?insight.personalisedQuest:displayQuest}</p>
              {insight&&insight.personalisedQuest&&(
                <p style={{fontSize:11,lineHeight:1.6,color:"#9a8a60",margin:"10px 0 0",fontFamily:"Calibri,sans-serif",fontStyle:"italic",borderTop:"1px solid rgba(183,149,11,0.2)",paddingTop:8}}>{displayQuest}</p>
              )}
            </div>

            {/* CTA — Draw Cards */}
            <div style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:14,padding:"26px 22px"}}>
              <p style={{fontSize:13,color:"#8a7f6e",margin:"0 0 18px",textAlign:"center"}}>The Hero's Journey Workshop is where your locked abilities are revealed — alongside 20 other adventurers, over 3 immersive days.</p>
              <div style={{display:"flex",gap:12,flexWrap:"wrap",justifyContent:"center"}}>
                <button onClick={()=>{setShowCards(true);window.scrollTo({top:0,behavior:"instant"});}} style={{background:`linear-gradient(135deg,${data.color},${data.color}cc)`,border:"none",borderRadius:8,padding:"12px 24px",color:"#fff",fontWeight:700,fontFamily:"Georgia",fontSize:14,cursor:"pointer",letterSpacing:"0.04em",display:"flex",alignItems:"center",gap:8}}>
                  ✦ Draw Your Character Cards
                </button>
                <button onClick={reset} style={{background:"none",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"12px 20px",color:"#8a7f6e",cursor:"pointer",fontFamily:"Georgia",fontSize:13}}>Retake Test</button>
              </div>
            </div>
            </div>)}
          </div>
        );
      })()}
    </div>
  );
}
